sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    // Use your Person/People field
    if (gs.nil(current.people)) return;

    // split sys_ids (works for single or glide_list)
    var ids = (current.people + '').split(',');

    var user = new GlideRecord('sys_user');
    user.addQuery('sys_id', 'IN', ids);   
    user.addQuery('notification', 2);     
    user.addQuery('email', '!=', '');
    user.query();

    var seen = {};
    while (user.next()) {
        var addr = (user.email + '').trim().toLowerCase();
        if (!addr || seen[addr]) continue; 
        seen[addr] = true;

        email.addAddress('bcc', addr, user.getDisplayValue());
    }
})(current, template, email, email_action, event);
